                return {'error': 'invalid_request'}
            for att in attachments:
                if not all(k in att for k in ['filename', 'content_type', 'content_b64']):
                    return {'error': 'invalid_request'}
                if not isinstance(att['filename'], str) or any(ord(c) > 127 for c in att['filename']):
                    return {'error': 'invalid_request'}
                if '/' in att['filename'] or '\\' in att['filename']:
                    return {'error': 'invalid_name'}
                if not isinstance(att['content_type'], str):
                    return {'error': 'invalid_type'}
                # Check base64 validity
                try:
                    base64.b64decode(att['content_b64'], validate=True)
