                    return {'error': 'invalid_b64'}
    except (json.JSONDecodeError, AttributeError, TypeError):
        return {'error': 'invalid_request'}

    # Build the message
    msg = EmailMessage()

    msg['From'] = request['from']
    msg['To'] = ', '.join(request['to'])

    # Encode subject using RFC 2047 if needed
    def encode_subject(subject):
        if any(ord(c) > 127 for c in subject):
            encoded = subject.encode('utf-8')
            return '=?utf-8?B?' + base64.b64encode(encoded).decode('ascii') + '?'
        return subject

    msg['Subject'] = encode_subject(request['subject'])
    msg['Date'] = formatdate(timezone='UTC')
    msg['Message-ID'] = '<' + request['message_id'][1:-1] + '>'
    msg['MIME-Version'] = '1.0'

